"""System diagnostic checks."""

import os
import shutil
import sys

from .models import CheckResult, CheckStatus


def run_checks(verbose: bool = False) -> list[CheckResult]:  # noqa: ARG001
    """Run system diagnostic checks."""
    results = []
    results.append(_check_python_version())
    results.append(_check_disk_space())
    results.append(_check_required_tools())
    results.append(_check_version_compatibility())
    return results


def _check_python_version() -> CheckResult:
    """Check Python version compatibility."""
    major, minor = sys.version_info[:2]

    if (major, minor) < (3, 9):
        return CheckResult(
            name="system.python_version",
            category="system",
            status=CheckStatus.FAIL,
            message=f"Python {major}.{minor} is not supported. Requires >= 3.9.",
            fix_hint="Upgrade Python to 3.9 or later.",
        )

    if (major, minor) >= (3, 9):
        return CheckResult(
            name="system.python_version",
            category="system",
            status=CheckStatus.PASS,
            message=f"Python {sys.version.split()[0]} (supported).",
        )

    return CheckResult(
        name="system.python_version",
        category="system",
        status=CheckStatus.PASS,
        message=f"Python {sys.version.split()[0]}",
    )


def _check_disk_space() -> CheckResult:
    """Check available disk space in home directory."""
    try:
        home = os.path.expanduser("~")
        stat = os.statvfs(home)
        free_gb = (stat.f_bavail * stat.f_frsize) / (1024**3)

        if free_gb < 1:
            return CheckResult(
                name="system.disk_space",
                category="system",
                status=CheckStatus.FAIL,
                message=f"Low disk space: {free_gb:.1f} GB free in home directory.",
                fix_hint="Free up disk space. Environment installs require at least 1 GB.",
            )
        if free_gb < 5:
            return CheckResult(
                name="system.disk_space",
                category="system",
                status=CheckStatus.WARN,
                message=f"Disk space is limited: {free_gb:.1f} GB free.",
            )
        return CheckResult(
            name="system.disk_space",
            category="system",
            status=CheckStatus.PASS,
            message=f"{free_gb:.1f} GB free disk space.",
        )
    except (OSError, AttributeError):
        # statvfs not available on some platforms
        return CheckResult(
            name="system.disk_space",
            category="system",
            status=CheckStatus.SKIP,
            message="Could not check disk space on this platform.",
        )


def _check_required_tools() -> CheckResult:
    """Check for required/useful system tools."""
    tools = {
        "git": ("required", "Version control"),
        "ssh": ("optional", "Remote compute access"),
        "tmux": ("optional", "Agent session management"),
        "gh": ("optional", "GitHub issue reporting"),
    }

    missing_required = []
    missing_optional = []
    found = []

    for tool, (importance, desc) in tools.items():
        if shutil.which(tool):
            found.append(tool)
        elif importance == "required":
            missing_required.append(f"{tool} ({desc})")
        else:
            missing_optional.append(f"{tool} ({desc})")

    if missing_required:
        return CheckResult(
            name="system.required_tools",
            category="system",
            status=CheckStatus.FAIL,
            message=f"Missing required tools: {', '.join(missing_required)}",
            fix_hint="Install missing tools via your package manager.",
        )

    if missing_optional:
        return CheckResult(
            name="system.required_tools",
            category="system",
            status=CheckStatus.WARN,
            message=(
                f"Found: {', '.join(found)}."
                f" Optional tools not found: {', '.join(missing_optional)}"
            ),
        )

    return CheckResult(
        name="system.required_tools",
        category="system",
        status=CheckStatus.PASS,
        message=f"All tools available: {', '.join(found)}",
    )


def _check_version_compatibility() -> CheckResult:
    """Check if qbraid-core and qbraid-cli versions are compatible."""
    try:
        import importlib.metadata

        core_version = importlib.metadata.version("qbraid-core")

        try:
            cli_version = importlib.metadata.version("qbraid-cli")
        except importlib.metadata.PackageNotFoundError:
            return CheckResult(
                name="system.version_compatibility",
                category="system",
                status=CheckStatus.SKIP,
                message=f"qbraid-core {core_version} installed. qbraid-cli not installed.",
            )

        # Extract major.minor for comparison
        core_parts = core_version.split(".")[:2]
        cli_parts = cli_version.split(".")[:2]

        try:
            core_mm = tuple(int(x) for x in core_parts)
            cli_mm = tuple(int(x) for x in cli_parts)
        except ValueError:
            return CheckResult(
                name="system.version_compatibility",
                category="system",
                status=CheckStatus.WARN,
                message=f"Cannot parse versions: core={core_version}, cli={cli_version}",
                details={"core": core_version, "cli": cli_version},
            )

        if core_mm[0] != cli_mm[0]:
            return CheckResult(
                name="system.version_compatibility",
                category="system",
                status=CheckStatus.WARN,
                message=(
                    f"Major version mismatch: qbraid-core {core_version},"
                    f" qbraid-cli {cli_version}"
                ),
                fix_hint="Update both packages to matching versions.",
                details={"core": core_version, "cli": cli_version},
            )

        return CheckResult(
            name="system.version_compatibility",
            category="system",
            status=CheckStatus.PASS,
            message=f"qbraid-core {core_version}, qbraid-cli {cli_version}",
            details={"core": core_version, "cli": cli_version},
        )
    except Exception as exc:
        return CheckResult(
            name="system.version_compatibility",
            category="system",
            status=CheckStatus.ERROR,
            message=f"Could not check version compatibility: {exc}",
        )
